let imageUrl = String($json.original_url || '').trim();
const driveId = imageUrl.match(/(?:open\?id=|uc\?(?:export=[^&]+&)?id=|thumbnail\?id=|file\/d\/|[?&]id=)([A-Za-z0-9_-]+)/)?.[1] || String($json.file_id || '').trim();
if (driveId) imageUrl = `https://drive.google.com/uc?export=download&id=${driveId}`;
if (imageUrl.includes('dropbox.com') && imageUrl.includes('dl=0')) imageUrl = imageUrl.replace('dl=0', 'dl=1');
if (imageUrl.includes('sharepoint.com') || imageUrl.includes('1drv.ms')) imageUrl = imageUrl.split('?')[0] + '?download=1';
return { json: { ...$json, file_id: driveId, direct_download_url: imageUrl, preview_url: driveId ? `https://drive.google.com/uc?export=view&id=${driveId}` : imageUrl } };

const output = [];
const norm = (value) => String(value || '').trim().toLowerCase().replace(/\s+/g, ' ');
const get = (row, ...names) => {
  for (const name of names) {
    const wanted = norm(name);
    const found = Object.entries(row).find(([field, value]) => norm(field) === wanted && String(value || '').trim());
    if (found) return found[1];
  }
  return '';
};
const driveIds = (value) => {
  const text = String(value || '').replace(/&amp;/g, '&').replace(/\\&/g, '&');
  const ids = [];
  for (const match of text.matchAll(new RegExp('/d/([A-Za-z0-9_-]+)', 'g'))) ids.push(match[1]);
  for (const match of text.matchAll(new RegExp('[?&]id=([A-Za-z0-9_-]+)', 'g'))) ids.push(match[1]);
  return [...new Set(ids)];
};
const types = { 'bài viết thường': 'post', 'bài viết': 'post', 'facebook reel': 'facebook_reel', 'youtube short': 'youtube_short', 'youtube video thường': 'youtube_video', 'youtube video': 'youtube_video', 'tiktok': 'tiktok_video', 'tiktok video': 'tiktok_video', 'video tiktok': 'tiktok_video', 'tiktok_video': 'tiktok_video' };
for (const item of $input.all()) {
  const source = item.json || {};
  let postType = types[norm(get(source, 'Loại nội dung', 'postType') || 'Bài viết thường')] || 'post';
  if (postType === 'post' && /tiktok/.test(norm(get(source, 'Nền tảng', 'Nền tảng đăng', 'platform')))) postType = 'tiktok_video';
  const imageIds = driveIds(get(source, 'Hình ảnh công việc', 'linkHinhAnh', 'images'));
  const videoValue = postType === 'tiktok_video' ? get(source, 'Video TikTok', 'videoTikTok', 'Video đính kèm', 'videoUrl') : postType === 'facebook_reel' ? get(source, 'Video Reel', 'Video Reel ', 'videoReel') : postType === 'youtube_short' ? get(source, 'Video Short', 'Video Short ', 'videoShort') : postType === 'youtube_video' ? get(source, 'Video thường', 'Video thường ', 'Video', 'videoUrl') : get(source, 'Video đính kèm', 'videoUrl');
  const videoId = driveIds(videoValue)[0] || '';
  if (postType === 'tiktok_video' && !videoId) throw new Error('Video TikTok cần là link file Google Drive.');
  const title = postType === 'youtube_short' ? get(source, 'Tiêu đề Youtube Short', 'Tiêu đề YouTube Short', 'youtubeTitle') : postType === 'youtube_video' ? get(source, 'Tiêu đề youtube video thường', 'Tiêu đề YouTube video thường', 'youtubeTitle') : '';
  const description = postType === 'youtube_short' ? get(source, 'Mô tả Youtube Short', 'Mô tả YouTube Short', 'youtubeDescription') : postType === 'youtube_video' ? get(source, 'Mô tả youtube video thường', 'Mô tả YouTube video thường', 'youtubeDescription') : postType === 'facebook_reel' ? get(source, 'Mô tả Reel', 'description') : '';
  const platformRaw = norm(get(source, 'Nền tảng', 'Nền tảng đăng', 'platform'));
  const hasTikTok = /tiktok/.test(platformRaw) || postType === 'tiktok_video';
  const hasFacebook = /facebook|fanpage/.test(platformRaw) || postType === 'facebook_reel';
  const hasLinkedIn = /linkedin/.test(platformRaw) && postType === 'post';
  const hasYouTube = /youtube/.test(platformRaw) || postType === 'youtube_short' || postType === 'youtube_video';
  const platform = hasTikTok ? 'tiktok' : hasFacebook && hasLinkedIn ? 'both' : hasFacebook ? 'facebook' : hasLinkedIn ? 'linkedin' : hasYouTube ? 'youtube' : 'facebook';
  const images = imageIds.map((fileId, index) => ({ fileId, fileName: 'google-drive-image-' + (index + 1), originalUrl: 'https://drive.google.com/open?id=' + fileId, previewUrl: 'https://drive.google.com/file/d/' + fileId + '/preview', mimeType: 'image/*' }));
  const row = { sourceRowId: String(get(source, 'Dấu thời gian', 'Timestamp', 'timestamp', 'row_number') || Date.now()), employeeName: String(get(source, 'Tên nhân viên', 'Tên', 'Email address') || 'Chưa xác định'), note: String(get(source, 'Ghi chú công việc', 'Ghi chú', 'note') || '').trim(), postType, platform, targetFB: hasFacebook, targetLI: hasLinkedIn, targetYouTube: hasYouTube, targetTikTok: hasTikTok, tiktokCaption: String(get(source, 'Caption TikTok', 'Mô tả TikTok', 'tiktokContent') || '').trim(), youtubeTitle: String(title || '').trim(), youtubeDescription: String(description || '').trim(), video: videoId ? { fileId: videoId, fileName: 'google-drive-video', url: 'https://drive.google.com/uc?export=download&id=' + videoId, mimeType: 'video/mp4' } : null, images, sheetRow: { ...source } };
  output.push({ json: { ...item.json, _row: row } });
}
return output;

const row = $('Chuẩn hóa row và nền tảng').first().json._row || {};
const ai = $input.first()?.json || {};
const texts = [];
const walk = (value, depth = 0) => { if (depth > 8 || value === null || value === undefined) return; if (typeof value === 'string') { if (value.trim()) texts.push(value.trim()); return; } if (Array.isArray(value)) { value.forEach((item) => walk(item, depth + 1)); return; } if (typeof value === 'object') Object.values(value).forEach((item) => walk(item, depth + 1)); };
walk(ai);
const raw = texts.find((text) => text.includes('{')) || texts.sort((a, b) => b.length - a.length)[0] || '';
let parsed = {};
try { parsed = JSON.parse(raw); } catch { const start = raw.indexOf('{'); const end = raw.lastIndexOf('}'); if (start >= 0 && end > start) { try { parsed = JSON.parse(raw.slice(start, end + 1)); } catch {} } }
const tiktokContent = String(parsed.tiktok || row.tiktokCaption || row.note || '').trim();
if (row.targetTikTok && !tiktokContent) throw new Error('AI chưa tạo được caption TikTok.');
const youtubeTitle = String(parsed.youtubeTitle || row.youtubeTitle || '').trim();
const youtubeDescription = String(parsed.youtubeDescription || row.youtubeDescription || '').trim();
return [{ json: { _row: row, tt_content: row.targetTikTok ? tiktokContent : '', fb_content: String(parsed.facebook || '').trim(), li_content: String(parsed.linkedin || '').trim(), yt_content: String(parsed.youtube || youtubeDescription || youtubeTitle || 'Video EPCB').trim(), youtubeTitle, youtubeDescription } }];
